// NICU Manual service worker (generated by chatbot/build_knowledge.py from pwa/sw.template.js).
// Pages are network-first so a connected device always shows the live manual; the cached copy
// is used only when offline. Chapters, styles and chat data are stored at install; images and
// downloads are stored the first time they are opened.
const VERSION = "20261023182422";
const BUILT = "October 23, 2026";
const PRECACHE = [
 "./",
 "DR.html",
 "VLBW.html",
 "admission.html",
 "cardiovascular.html",
 "chatbot/nicu-manual-knowledge.md",
 "custom.css",
 "death-workflows.html",
 "discharge.html",
 "documentation.html",
 "dotPhrases.html",
 "endocrine.html",
 "gastrointestinal.html",
 "genetics-lluch.html",
 "hemonc.html",
 "index.html",
 "infectious-disease.html",
 "lluch-formulary.html",
 "manifest.webmanifest",
 "neurology.html",
 "nutrition-fluid.html",
 "operations.html",
 "periviability.html",
 "phone-numbers.html",
 "publications.html",
 "pwa/apple-touch-icon.png",
 "pwa/favicon-64.png",
 "pwa/icon-192.png",
 "pwa/icon-512.png",
 "pwa/icon-maskable-512.png",
 "references.html",
 "renal-urology.html",
 "respiratory.html",
 "search.json",
 "site_libs/bootstrap/bootstrap-ab9a0a4e0698b5410a6d6c29fb8c72b9.min.css",
 "site_libs/bootstrap/bootstrap-icons.css",
 "site_libs/bootstrap/bootstrap-icons.woff",
 "site_libs/bootstrap/bootstrap.min.js",
 "site_libs/clipboard/clipboard.min.js",
 "site_libs/kePrint-0.0.1/kePrint.js",
 "site_libs/lightable-0.0.1/lightable.css",
 "site_libs/quarto-contrib/glightbox/glightbox.min.css",
 "site_libs/quarto-contrib/glightbox/glightbox.min.js",
 "site_libs/quarto-contrib/glightbox/lightbox.css",
 "site_libs/quarto-diagram/mermaid-init.js",
 "site_libs/quarto-diagram/mermaid.css",
 "site_libs/quarto-diagram/mermaid.min.js",
 "site_libs/quarto-html/anchor.min.js",
 "site_libs/quarto-html/popper.min.js",
 "site_libs/quarto-html/quarto-syntax-highlighting-15634bcf2e68342d4ad2dfa704d543f6.css",
 "site_libs/quarto-html/quarto.js",
 "site_libs/quarto-html/tabsets/tabsets.js",
 "site_libs/quarto-html/tippy.css",
 "site_libs/quarto-html/tippy.umd.min.js",
 "site_libs/quarto-nav/headroom.min.js",
 "site_libs/quarto-nav/quarto-nav.js",
 "site_libs/quarto-search/autocomplete.umd.js",
 "site_libs/quarto-search/fuse.min.js",
 "site_libs/quarto-search/quarto-search.js",
 "surgical.html",
 "telemedicine.html",
 "transfer.html",
 "vaccine.html"
];
const CACHE = "nicu-manual-" + VERSION;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) =>
      // one failed file shouldn't block the install
      Promise.all(PRECACHE.map((url) => cache.add(new Request(url, { cache: "reload" })).catch(() => {})))
    ).then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k.startsWith("nicu-manual-") && k !== CACHE).map((k) => caches.delete(k)))
    ).then(() => self.clients.claim())
  );
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "built" && event.ports[0]) event.ports[0].postMessage({ built: BUILT });
});

const isPage = (req, url) => req.mode === "navigate" || url.pathname.endsWith(".html") ||
  url.pathname.endsWith("/") || url.pathname.endsWith(".md") || url.pathname.endsWith("search.json");

self.addEventListener("fetch", (event) => {
  const req = event.request;
  const url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== self.location.origin || !url.href.startsWith(self.registration.scope)) return;
  event.respondWith(isPage(req, url) ? networkFirst(req) : cacheFirst(req));
});

async function networkFirst(req) {
  const cache = await caches.open(CACHE);
  try {
    const res = await fetch(req);
    if (res.ok) cache.put(req, res.clone());
    return res;
  } catch (e) {
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    if (req.mode === "navigate") return (await cache.match("index.html")) || Response.error();
    return Response.error();
  }
}

async function cacheFirst(req) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(req, { ignoreSearch: true });
  if (hit) return hit;
  try {
    const res = await fetch(req);
    if (res.ok && res.type === "basic") cache.put(req, res.clone());
    return res;
  } catch (e) {
    return Response.error(); // offline and never viewed: the image or file just doesn't load
  }
}
